const readline = require("readline");

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

const lines = [];
rl.on("line", (line) => {
  lines.push(line);

  if (lines.length === 3) {
    // 这里replaceAll的原因是：有考友反馈实际考试存在20%的用例输入类似于 [10,20,5] 这种
    const cakes = lines[0]
      .replaceAll(/[\[\]]/g, "")
      .split(",")
      .map(Number);
    const gifts = lines[1]
      .replaceAll(/[\[\]]/g, "")
      .split(",")
      .map(Number);
    const x = parseInt(lines[2]);

    console.log(getResult(cakes, gifts, x));

    lines.length = 0;
  }
});

function getResult(cakes, gifts, x) {
  cakes.sort((a, b) => a - b);

  let ans = 0;
  for (let gift of gifts) {
    if (x <= gift) continue;

    const maxCake = x - gift;
    let i = searchLast(cakes, maxCake);

    if (i >= 0) {
      ans += i + 1;
    } else {
      i = -i - 1;
      ans += i;
    }
  }

  return ans;
}

function searchLast(arr, target) {
  let low = 0;
  let high = arr.length - 1;

  while (low <= high) {
    const mid = (low + high) >> 1;
    const midVal = arr[mid];

    if (midVal > target) {
      high = mid - 1;
    } else if (midVal < target) {
      low = mid + 1;
    } else {
      // 向右延伸判断，mid是否为target数域的右边界，即最后一次出现的位置
      if (mid == arr.length - 1 || arr[mid] != arr[mid + 1]) {
        return mid;
      } else {
        low = mid + 1;
      }
    }
  }

  return -low - 1; // 找不到则返回插入位置
}

